// The Antenna mark in the app: a vector drawn from the same geometry as the SVGs and icons (lib/theme/logo_geometry.dart
// is generated by docs/design/logo/build.py). The app has no raster copies of the logo, so the mark is sharp at any scale.

import 'package:flutter/widgets.dart';

import 'logo_geometry.dart';
import 'tokens.dart';

/// The mark without a background. Logo blue by default; white on a blue tile.
class AntennaMark extends StatelessWidget {
  const AntennaMark({super.key, this.height = 28, this.color});
  final double height;
  final Color? color;

  static double get aspect {
    final b = LogoGeometry.bounds;
    return (b[2] - b[0]) / (b[3] - b[1]);
  }

  @override
  Widget build(BuildContext context) => SizedBox(
        width: height * aspect,
        height: height,
        child: CustomPaint(painter: AntennaMarkPainter(color ?? XColors.brand)),
      );
}

/// App icon: the white mark on a rounded blue tile (like AppIcon, without the shadow).
class AntennaAppIcon extends StatelessWidget {
  const AntennaAppIcon({super.key, this.size = 40, this.radius});
  final double size;

  /// Defaults to 22.5 % of the side (the macOS icon grid).
  final double? radius;

  @override
  Widget build(BuildContext context) => Container(
        width: size,
        height: size,
        alignment: Alignment.center,
        decoration: BoxDecoration(
          color: XColors.brand,
          borderRadius: BorderRadius.circular(radius ?? size * 0.225),
        ),
        child: AntennaMark(height: size * 0.70, color: XColors.markOnBrand),
      );
}

class AntennaMarkPainter extends CustomPainter {
  const AntennaMarkPainter(this.color);
  final Color color;

  @override
  void paint(Canvas canvas, Size size) {
    final b = LogoGeometry.bounds;
    final w = b[2] - b[0], h = b[3] - b[1];
    final s = (size.width / w) < (size.height / h) ? size.width / w : size.height / h;
    canvas.save();
    canvas.translate((size.width - w * s) / 2, (size.height - h * s) / 2);
    canvas.scale(s);
    canvas.translate(-b[0], -b[1]);
    final stroke = Paint()
      ..color = color
      ..style = PaintingStyle.stroke
      ..strokeCap = StrokeCap.round
      ..strokeWidth = LogoGeometry.stroke
      ..isAntiAlias = true;
    final dashes = Path();
    for (final a in LogoGeometry.arcs) {
      dashes
        ..moveTo(a[0], a[1])
        ..arcToPoint(Offset(a[2], a[3]), radius: Radius.circular(a[4]), clockwise: a[5] == 1);
    }
    for (final l in LogoGeometry.lines) {
      dashes
        ..moveTo(l[0], l[1])
        ..lineTo(l[2], l[3]);
    }
    canvas.drawPath(dashes, stroke);
    final bar = Path();
    for (final l in LogoGeometry.crossbar) {
      bar
        ..moveTo(l[0], l[1])
        ..lineTo(l[2], l[3]);
    }
    canvas.drawPath(bar, stroke..strokeWidth = LogoGeometry.crossbarStroke);
    final c = LogoGeometry.circle;
    canvas.drawCircle(Offset(c[0], c[1]), c[2], Paint()..color = color);
    canvas.restore();
  }

  @override
  bool shouldRepaint(AntennaMarkPainter old) => old.color != color;
}
